 async function ensureContext(){if(o)return o;const outline=await api<Outline>('','POST',{kind:'quick',title:'Untitled production'});await navigate({production_id:outline.production.id,shot_id:outline.shots[0]?.id||null,stage:'storyboard'});return outline;}
 async function launch(tool:Tool){
  await prepare();
  if(tool==='quick'||tool==='story'){closeOverlays();openModal(tool);return;}
  if(tool==='assets'){overlayReturn.current=routeLive.current;if(inProject)setReturnRoute(routeLive.current);await restoreRoute({page:'tool',tool});return;}
  if(tool==='precision'){closeOverlays();if(inProject)setReturnRoute(routeLive.current);commit({page:'tool',tool});return;}
  if(['world','edit','camera','movements'].includes(tool)){let outline=await ensureContext();if(tool==='world'||tool==='edit'){await navigate({production_id:outline.production.id,stage:tool==='world'?'develop':'edit'});if(tool==='world')setDevelopView('world');return;}let shot=outline.shots.find(s=>s.id===w.shot_id)||outline.shots[0];if(!shot){const episode=outline.episodes[0];if(episode&&!episode.scenes.length){const e=await api<Episode>('/'+outline.production.id+'/scenes','POST',{episode_id:episode.id,expected_revision:episode.revision,title:'Opening'});outline.episodes[0]=e;}shot=await api<Shot>('/'+outline.production.id+'/shots','POST',{title:'New shot',episode_id:outline.episodes[0]?.id,story_scene_id:outline.episodes[0]?.scenes[0]?.id});}await navigate({production_id:outline.production.id,shot_id:shot.id,stage:tool==='camera'?'storyboard':'generate',board_view:tool==='camera'?'image':'board'});if(tool==='camera')setCameraShot(shot.id);else setMovementShot(shot.id);commit({...routeLive.current,overlay:tool as 'camera'|'movements'},true);return;}
  if(inProject&&o&&(tool!=='scripts'||o.production.kind==='story')){const kind=tool==='scripts'?'script':tool;const id=kind==='script'?undefined:window.productionBridge.selected()[kind as 'image'|'video'];if(id&&selected?.[kind as 'image'|'video']?.id!==id){const location=await api<any>('/locate','POST',{kind,id});await navigate({...location,stage:kind==='image'?'storyboard':'generate',board_view:kind==='image'?'image':'board'});return;}if(tool==='scripts'||selected){await navigate({stage:tool==='scripts'?'script':tool==='image'?'storyboard':'generate',board_view:tool==='image'?'image':'board'});return;}}
  if(inProject)setReturnRoute(routeLive.current);const kind=tool==='scripts'?'script':tool;let id=window.productionBridge.selected()[kind as 'image'|'video'|'script'];if(kind==='script'&&!id){const d=await window.productionBridge.newMedia('script');id=d.id;}await restoreRoute({page:'tool',tool,media:id?{kind,id}:undefined});
 }
