 async function openLibraryItem(item:LibraryItem){
  if(item.kind==='asset'){overlayReturn.current=routeLive.current;await restoreRoute({page:'tool',tool:'assets',media:{kind:'asset',id:item.id}});return;}
  if(item.kind==='export'){const t=await service('editing/timelines/'+item.record.timeline_id);await navigate({production_id:t.production_id,episode_id:t.episode_id,stage:'edit'});return;}
  if(item.kind==='upload'){await launch('edit');return;}
  const kind=item.kind==='script'?'script':item.kind;let id=item.draftId||item.id;
  if(item.kind==='image'&&item.status!=='draft'&&!item.draftId){await window.productionBridge.useImage(item.record,'base');id=window.productionBridge.selected().image!;}
  if(item.kind==='video'&&item.status==='take'&&!item.draftId){const d=await service('jobs/'+item.id+'/reuse','POST',{});id=d.id;}
  if(item.status==='archived')throw Error('Restore this draft before opening it.');if(item.record.story_context&&kind!=='script'){const location=await api<any>('/locate','POST',{kind,id});await navigate({...location,stage:kind==='image'?'storyboard':'generate',board_view:kind==='image'?'image':'board'});return;}await restoreRoute({page:'tool',tool:kind==='script'?'scripts':kind as Tool,media:{kind,id}});
 }
